// The ready-made object library. Picking one needs no 3D skills and no review.
// The GLB and PNG files are generated by scripts/library/ into public/library/.

export type LibraryObject = {
  id: string;
  name: string;
  /** GLB, 1 m across, centred, sitting on the ground. */
  model: string;
  /** Transparent PNG, 256 px square. */
  thumbnail: string;
};

const objects = [
  { id: "pizza", name: "Pizza slice" },
  { id: "cup", name: "Coffee cup" },
  { id: "gift", name: "Gift box" },
  { id: "star", name: "Star" },
  { id: "heart", name: "Heart" },
  { id: "note", name: "Speech bubble" },
];

export const library: LibraryObject[] = objects.map((o) => ({
  ...o,
  model: `/library/${o.id}.glb`,
  thumbnail: `/library/${o.id}.png`,
}));

export function libraryObject(id: string): LibraryObject | undefined {
  return library.find((o) => o.id === id);
}
